1	import {once} from 'node:events';
2	import type {WebSocket} from 'ws';
3	import {askOnOpen, connectClient, framesUntil, startEngine, stopEngines} from './wsTestSupport.js';
4	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
5	import type {ChatSession} from '../types/session.js';
6	
7	// The engine's own spec promises sessions persist across disconnections; the transport used to erase them on close.
8	
9	const FAIL_FAST_MS = 5_000;
10	const settle = (ms = 50) => new Promise<void>(resolve => setTimeout(resolve, ms));
11	
12	// The id is only ever announced in the connected frame, and both tests below need it after the fact.
13	const announcedId = (client: WebSocket): (() => string) => {
14	  let sessionId = '';
15	  client.on('message', raw => {
16	    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
17	    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
18	  });
19	  return () => sessionId;
20	};
21	
22	const turnThenClose = async (store: InMemorySessionStore, onDisconnect?: (sessionId: string) => void) => {
23	  const url = await startEngine(store, onDisconnect);
24	  const {client, finished} = askOnOpen(url);
25	  // Attached before any frame is delivered: delivery is asynchronous, so this still precedes the connected frame.
26	  const sessionId = announcedId(client);
27	
28	  await finished;
29	  client.close();
30	  await once(client, 'close');
31	  await settle();
32	
33	  return {held: await store.count(), session: (await store.get(sessionId())) as ChatSession | undefined};
34	};
35	
36	describe('a conversation whose socket closes', () => {
37	  afterEach(stopEngines);
38	
39	  // prettier-ignore
40	  it('survives the close with its entries intact', async () => {
41	    const store = new InMemorySessionStore();
42	
43	    const {held, session} = await turnThenClose(store);
44	
45	    expect({held, entries: session?.entries.map(entry => entry.role)}).toEqual({
46	      held: 1,
47	      entries: ['user', 'assistant'],
48	    });
49	  }, FAIL_FAST_MS);
