// A transport failure must reach the awaiting test as a rejection: an 'error' event with no listener
// is reported against whichever test the worker is running, and a pending frames promise would hang out the suite's timeout.
const failures = new WeakMap<WebSocket, Error>();

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  client.on('error', error => {
    failures.set(client, error instanceof Error ? error : new Error(String(error)));
  });
  clients.push(client);
  return client;
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  const frames = new Promise<string[]>((resolve, reject) => {
    const rejectPending = (): void => {
      reject(failures.get(client) ?? new Error(`closed before the ${until} frame arrived`));
    };
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
    if (client.readyState === WebSocket.CLOSED) rejectPending();
    else client.once('close', rejectPending);
  });
  // Teardown terminates clients whose test already stopped awaiting: the rejection must not surface as an unhandled one.
